    end
    on_intel do
      url "https://github.com/astrona-io/codesynapse/releases/download/v0.0.8/codesynapse-darwin-amd64"
      sha256 "ab35399a5beeea3faf3d0afb94bfd667a7bc11f2e87d4fa7a1923b8f361e36ee"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/astrona-io/codesynapse/releases/download/v0.0.8/codesynapse-linux-arm64"
      sha256 "e374bfb2f41cfb26bb02649fa280b2bfb556b3b1595117857c218e19bf279723"
